problems=[task.generate_problem(20000, random_seed=i) for i in range(3)]

def timefunc(func):
    t0=time.perf_counter()
    for p in problems:
        func(p)
    return time.perf_counter()-t0

def ref_func(p):
    return task.solve(copy.deepcopy(p))

def hash_func(p):
    return {'digest': hashlib.sha256(p['plaintext']).digest()}
